# Статья 41: Oracle → Odoo (альтернатива Oracle): какие продукты Oracle у среднего бизнеса, из чего складываются расходы,
# когда Odoo подходит и когда лучше остаться, выгрузка данных, сопоставление с моделями Odoo, загрузка через load() с внешними ID.
# Тема – по мотивам блога git.gmbh, текст свой. Языки: en, de, ru, uk; fr/el – английская версия.
# Проверенные факты (WebSearch 25.11.2026): NetSuite куплен Oracle в 2016, подписка зависит от модулей и пользователей;
# Premier Support EBS 12.2 и JD Edwards EnterpriseOne 9.2 – «не меньше чем до 2036», Oracle продлевает ежегодно (новые страницы – 2037);
# стандартная ежегодная поддержка Oracle – 22 % от нетто-стоимости лицензий, индексируется.

ORACLE_POST = {
    "slug": "oracle-alternative-odoo-netsuite-jd-edwards-e-business-suite-migration",
    "date": "2026-11-25",
    "tags": ["Odoo", "Oracle", "Migration", "ERP"],
    "code": {
        "load": ("python · load customers exported from Oracle (CSV) into Odoo 17 – safe to run again", """# customers.csv – exported from Oracle (EBS/JDE: SQL query; NetSuite: saved search → CSV)
# columns: CUSTOMER_ID;NAME;EMAIL;VAT;COUNTRY   (COUNTRY = ISO code, e.g. DE)
import csv
import xmlrpc.client

URL, DB, USER, KEY = "https://odoo.example.com", "mydb", "import@example.com", "API-KEY"
uid = xmlrpc.client.ServerProxy(f"{URL}/xmlrpc/2/common").authenticate(DB, USER, KEY, {})
odoo = xmlrpc.client.ServerProxy(f"{URL}/xmlrpc/2/object", allow_none=True)

# "id" = external ID: the old Oracle number stays attached to the Odoo record,
# so a second run UPDATES the same partners instead of creating duplicates
fields = ["id", "name", "email", "vat", "country_id/id", "is_company"]
rows = []
with open("customers.csv", newline="", encoding="utf-8") as f:
    for r in csv.DictReader(f, delimiter=";"):
        rows.append([f"__import__.oracle_cust_{r['CUSTOMER_ID']}", r["NAME"].strip(),
                     r["EMAIL"].strip(), r["VAT"].strip(), f"base.{r['COUNTRY'].strip().lower()}", "1"])

for i in range(0, len(rows), 500):                       # batches of 500
    res = odoo.execute_kw(DB, uid, KEY, "res.partner", "load", [fields, rows[i:i + 500]])
    for m in res["messages"]:                            # row number + reason (bad VAT, unknown country …)
        print(m.get("type"), "row", i + m.get("record", 0), m.get("message"))
    if not res["ids"]:                                   # one error = the whole batch is rolled back
        raise SystemExit(f"batch from row {i} failed – fix the CSV and run again")
    print(f"rows {i}–{i + len(res['ids']) - 1}: ok")"""),
    },
    "links": [
        ("Blog: switching to Odoo from an old ERP – cut-over plan", "@blog:switch-to-odoo-old-erp-cutover-plan-data-migration-parallel-run"),
        ("Blog: what Odoo really costs in Germany", "@blog:odoo-costs-licence-hosting-implementation-germany"),
        ("Blog: Odoo or SAP – real costs for four companies", "@blog:odoo-vs-sap-business-one-real-cost-salon-bakery-warehouse-car-repair"),
        ("Odoo 17 external API (odoo.com)", "https://www.odoo.com/documentation/17.0/developer/reference/external_api.html"),
        ("Our hour packs", "@page:#packs"),
    ],
    "t": {},
}

